// packages/curriculum/src/catalog.ts
var skills = [
  ...skills_default.skills,
  ...skills_default2.skills,
  ...skills_default3.skills
];
var missions = [garden_default];
function skillsBySubject(subject) {
  return subject === "any" ? skills : skills.filter((s) => s.subject === subject);
}
function getMission(id) {
  const m = missions.find((x) => x.id === id);
  if (!m) throw new Error(`Unknown mission: ${id}`);
  return m;
}

// packages/shared/src/types.ts
function maxLevel(skill) {
  return Math.max(...Object.keys(skill.levels).map(Number).filter((n) => n >= 1 && n <= 6));
}

// packages/shared/src/text.ts
function stripAccents(s) {
  return s.normalize("NFD").replace(/[̀-ͯ]/g, "").normalize("NFC");
}
function basicNormalize(s) {
  return s.normalize("NFC").replace(/[’‘`´]/g, "'").replace(/œ/g, "oe").replace(/Œ/g, "OE").replace(/\s+/g, " ").trim().toLowerCase();
}
function looseNormalize(s) {
  return stripAccents(basicNormalize(s)).replace(/[.,;:!?«»"()\-'’]/g, " ").replace(/\s+/g, " ").trim();
}
function parseIntegers(s) {
  const matches = s.replace(/(\d)\s(?=\d{3}\b)/g, "$1").match(/-?\d+/g);
  return matches ? matches.map((m) => Number.parseInt(m, 10)) : [];
}
function parseSequence(s, expectedCount) {
  const text = s.replace(/[\u00a0\u202f]/g, " ");
  const parts = text.split(/[,;]+/).map((p) => p.trim()).filter(Boolean);
  const thousandsInParts = parts.flatMap((part) => /^\d{1,3}( \d{3})+$/.test(part) ? [Number(part.replace(/ /g, ""))] : (part.match(/\d+/g) ?? []).map(Number));
  const allSplit = (text.match(/\d+/g) ?? []).map(Number);
  const grouped = [];
  const groupable = [];
  for (const tok of text.split(/[,;\s-]+/).filter((x) => /^\d+$/.test(x))) {
    const last = grouped.length - 1;
    if (tok.length === 3 && last >= 0 && /^\d{1,3}$/.test(String(grouped[last])) && groupable[last]) {
      grouped[last] = grouped[last] * 1e3 + Number(tok);
      groupable[last] = false;
    } else {
      grouped.push(Number(tok));
      groupable.push(tok.length <= 3);
    }
  }
  const candidates = /[,;]/.test(text) ? [thousandsInParts, allSplit, grouped] : [allSplit, grouped];
  if (expectedCount !== void 0) {
    const fit = candidates.find((c) => c.length === expectedCount);
    if (fit) return fit;
  }
  return candidates[0];
}

// packages/shared/src/rng.ts
function createRng(seed) {
  let a = seed >>> 0;
  const next = () => {
    a = a + 1831565813 >>> 0;
    let t = a;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
  return {
    next,
    int(min, max) {
      return min + Math.floor(next() * (max - min + 1));
    },
    pick(arr) {
      if (arr.length === 0) throw new Error("pick() on an empty list");
      return arr[Math.floor(next() * arr.length)];
    },
    shuffle(arr) {
      const out = [...arr];
      for (let i = out.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1));
        [out[i], out[j]] = [out[j], out[i]];
      }
      return out;
    }
  };
}

