var games = [appleCrates, numberTrain, frogJump, wordFishing, mysteryStory, numberPath, hiddenWords, dominoes, listenGarden, gardenSays];
function getGame(id) {
  const g = games.find((x) => x.id === id);
  if (!g) throw new Error(`Unknown game: ${id}`);
  return g;
}
function generateGameRound(gameId, skillId, difficulty, seed, avoidKeys = [], opts = {}) {
  const g = getGame(gameId);
  if (!g.skills.includes(skillId)) throw new Error(`Game ${gameId} does not train ${skillId}`);
  return pickPreferred((s) => g.generate(skillId, difficulty, createRng(s), s, opts), seed, avoidKeys, opts.prefer);
}

