// packages/art/src/specs.ts
var artStyle = specs_default.style;
var artSpecs = specs_default.specs;
function getArtSpec(id) {
  return artSpecs.find((s) => s.id === id);
}

// packages/art/src/prompt.ts
var KIND_LINE = {
  background: "Photographie de d\xE9cor d\u2019arri\xE8re-plan pour un jeu \xE9ducatif destin\xE9 aux enfants",
  prop: "Photographie d\u2019un objet isol\xE9 pour un jeu \xE9ducatif destin\xE9 aux enfants",
  character: "Photographie d\u2019un vrai animal, personnage d\u2019un jeu \xE9ducatif destin\xE9 aux enfants",
  clip: "Clip vid\xE9o court et r\xE9aliste pour un jeu \xE9ducatif destin\xE9 aux enfants"
};
function buildPrompt(style, spec2) {
  const lines = [
    `${KIND_LINE[spec2.kind]}.`,
    `Sujet : ${spec2.brief}`,
    `Style : ${style.summary}`,
    `Couleurs de r\xE9f\xE9rence : ${style.palette.join(", ")}.`,
    `Toujours : ${style.always.join("; ")}.`,
    spec2.kind === "clip" ? "Vid\xE9o : de 2 \xE0 6 secondes, sans son, cam\xE9ra fixe, en boucle sans coupure visible (la derni\xE8re image s\u2019encha\xEEne avec la premi\xE8re), animal entier et centr\xE9, fond uni, clair et neutre." : spec2.transparent ? "Composition : un seul \xE9l\xE9ment, entier, centr\xE9, avec une marge libre tout autour, sur un fond enti\xE8rement transparent, sans sol, sans ombre port\xE9e sur le fond et sans d\xE9cor." : "Composition : image horizontale compl\xE8te, sans bordures ni cadres.",
    spec2.reference ? "Utilisez l\u2019image de r\xE9f\xE9rence comme mod\xE8le exact de l\u2019animal : m\xEAme pelage, m\xEAmes couleurs, m\xEAmes proportions et m\xEAmes marques; changez seulement la pose demand\xE9e." : "",
    `Ne jamais inclure : ${[...spec2.mustNot, ...style.never].join("; ")}.`
  ];
  return lines.filter(Boolean).join("\n");
}

