var depth = 0;
function tx(db, fn) {
  if (depth > 0) return fn();
  try {
    db.exec("BEGIN IMMEDIATE");
  } catch (e) {
    if (!db.isTransaction) throw e;
    db.exec("ROLLBACK");
    db.exec("BEGIN IMMEDIATE");
  }
  depth++;
  try {
    const r = fn();
    db.exec("COMMIT");
    return r;
  } catch (e) {
    try {
      db.exec("ROLLBACK");
    } catch {
      if (db.isTransaction) {
        try {
          db.exec("ROLLBACK");
        } catch {
        }
      }
    }
    throw e;
  } finally {
    depth--;
  }
}

