    x: typeof b?.x === "number" && Number.isFinite(b.x) ? Math.round(b.x) : null,
    y: typeof b?.y === "number" && Number.isFinite(b.y) ? Math.round(b.y) : null,
    scene: typeof b?.scene === "string" ? b.scene.slice(0, 40) : "garden"
