import { copyFileSync, existsSync as existsSync3, mkdirSync as mkdirSync3, readdirSync as readdirSync3, statSync as statSync2, writeFileSync as writeFileSync3 } from "node:fs";
import { join as join3 } from "node:path";
function createBackup(c, label = "manual") {
  const stamp = c.now().toISOString().replace(/[:.]/g, "-");
  const dir = join3(c.cfg.dataDir, "backups", `backup-${stamp}-${label.replace(/[^a-z0-9-]/gi, "")}`);
  mkdirSync3(join3(dir, "photos"), { recursive: true });
  const dbFile = join3(dir, "melina.db");
  c.db.exec(`VACUUM INTO '${dbFile.replace(/'/g, "''")}'`);
  const files = c.db.prepare("SELECT file_name FROM photos WHERE deleted_at IS NULL").all().map((r) => r.file_name);
  let copied = 0;
  const missing = [];
  for (const f of files) {
    const src = join3(photosDir(c), f);
    if (existsSync3(src)) {
      copyFileSync(src, join3(dir, "photos", f));
      copied++;
    } else missing.push(f);
  }
  const manifest = {
    createdAt: c.now().toISOString(),
    label,
    database: "melina.db",
    photos: copied,
    missingPhotos: missing,
    excluded: [".env (cl\xE9 de l\u2019API)"],
    restore: "Fermez l\u2019application. Copiez melina.db vers data/melina.db et le dossier photos vers data/photos. Rouvrez ensuite l\u2019application."
  };
  writeFileSync3(join3(dir, "manifest.json"), JSON.stringify(manifest, null, 2));
  return { folder: dir, ...manifest };
}
function listBackups(c) {
  const root = join3(c.cfg.dataDir, "backups");
  if (!existsSync3(root)) return [];
  return readdirSync3(root).filter((d) => d.startsWith("backup-")).map((d) => ({ name: d, createdAt: statSync2(join3(root, d)).mtime.toISOString() })).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

