  app.get("/art-files/:file", async (req, reply) => sendFile(req, reply, approvedFileInfo(c, String(req.params.file ?? "")), "public, max-age=31536000, immutable"));
  app.get("/api/backups", async () => listBackups(c));
  app.post("/api/backups", async () => createBackup(c, "manual"));
